import BreadcrumbAbout from "../components/BreadcrumbAbout";
import AboutUs from "../components/AboutUs";
import FooterOne from "../components/FooterOne";
import SecondaryFooter from "../components/SecondaryFooter";
import HeaderOne from "../components/HeaderOne";
import Preloader from "../helper/Preloader";
import { SEO } from "../utils/SEO";

const AboutUsPage = () => {
  const can = window.location.href;

  return (
    <>
    <SEO
        title="4ceps | About Us – Digital Healthcare Platform India"
        description="Learn more about 4ceps, a digital healthcare platform making medical services simple, affordable, and accessible across India."
        url={can}
      />
      {/* Preloader */}
      <Preloader />

      {/* HeaderOne */}
      <HeaderOne />

      {/* BreadcrumbAbout */}
      <BreadcrumbAbout />

      {/* AboutUs */}
      <AboutUs />

      <SecondaryFooter />

      {/* FooterOne */}
      <FooterOne />
    </>
  );
};

export default AboutUsPage;
